{
  "name": "bt_conn_timer_check",
  "confidence": "medium",
  "docstring": "Iterates over a Bluetooth connection's timer event descriptors under an IRQ-nested critical section and locks kernel events whose wrap-safe deadlines have expired.",
  "subsystem": "bt",
  "var_renames": {
    "result": "conn_ctx",
    "a2": "tick_delay",
    "v2": "irq_lock_nesting",
    "v3": "tick_base",
    "v4": "irq_restore_flag",
    "v5": "timer_group",
    "v6": "second_pass",
    "v8": "original_ctx",
    "v9": "timer_event",
    "v10": "deadline_expired",
    "v11": "tick_diff",
    "v12": "nesting_after_lock",
    "v13": "nesting_after_release",
    "v14": "saved_irq_flag"
  },
  "struct_hints": [
    {
      "offset": 1225,
      "meaning": "byte selecting timer group or link type from connection context"
    },
    {
      "offset": 88,
      "meaning": "connection state field cleared when a timer deadline expires"
    },
    {
      "offset": 12,
      "meaning": "uint32 event timestamp used for wrap-safe deadline comparison"
    },
    {
      "offset": 16,
      "meaning": "uint8 timer event armed/valid flag"
    },
    {
      "offset": 32,
      "meaning": "uint8 timer event completed/disabled flag"
    },
    {
      "offset": 16,
      "meaning": "current tick field in the timer block referenced by off_12AD9C (v3[4])"
    }
  ]
}
